<section class="admin-welcome"><div><h1><?= htmlspecialchars($title) ?></h1><p>Données réelles enregistrées par la plateforme.</p></div><?php if($type==='orders'): ?><div><a class="btn secondary" href="/admin/documents">Centre documentaire</a><a class="btn secondary" href="/admin/documents/export-commandes">Export Excel</a></div><?php elseif($type==='products'): ?><a class="btn primary" href="/admin/produits/nouveau">+ Ajouter un produit</a><?php endif ?></section>
