<?php foreach($items as $item): ?><tr data-search-row>
<?php if($type==='orders'): ?><td><strong><?= htmlspecialchars($item['reference']) ?></strong></td><td><?= htmlspecialchars($item['customer']) ?><br><small><?= htmlspecialchars($item['email']) ?></small></td><td><strong><?= number_format($item['total'],0,',',' ') ?> F</strong></td><td><?= htmlspecialchars($item['payment']) ?></td><td><form class="order-status-form" method="post" action="/admin/commandes/statut"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><select name="status"><?php foreach(['pending'=>'En attente','paid'=>'Payée','processing'=>'Préparation','shipping'=>'En livraison','completed'=>'Livrée','cancelled'=>'Annulée'] as $value=>$label): ?><option value="<?= $value ?>" <?= $item['status']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select><button class="btn primary">OK</button></form></td><td><?= date('d/m/Y H:i',strtotime($item['created_at'])) ?></td><td><a class="btn secondary" target="_blank" href="/admin/documents/commande?id=<?= (int)$item['id'] ?>">Commande</a> <a class="btn secondary" target="_blank" href="/admin/documents/livraison?id=<?= (int)$item['id'] ?>">Livraison</a></td>
<?php elseif($type==='users'): ?><td><strong><?= htmlspecialchars($item['name']) ?></strong><br><small>Créé le <?= date('d/m/Y',strtotime($item['created_at'])) ?></small></td><td><?= htmlspecialchars($item['email']) ?><br><small><?= htmlspecialchars($item['phone']??'—') ?></small></td><td><?= $item['role']==='instructor'?'Formateur':($item['role']==='admin'?'Administrateur':'Apprenant') ?></td><td><span class="status <?= $item['status']==='active'?'published':'draft' ?>"><?= $item['status']==='active'?'Actif':'OTP en attente' ?></span></td><td><div class="table-actions"><a class="btn secondary" href="/admin/utilisateurs/modifier?id=<?= (int)$item['id'] ?>">Gérer</a><?php if($item['status']!=='active'): ?><form method="post" action="/admin/utilisateurs/activer"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="btn primary">Activer</button></form><?php endif ?></div></td>
<?php else: ?><td><strong><?= htmlspecialchars($item['title']) ?></strong><br><small><?= htmlspecialchars($item['reference']) ?></small></td><td><?= htmlspecialchars($item['category']) ?></td><td><?= htmlspecialchars($item['stock']) ?></td><td><?= $item['promotional_price']!==null?'<strong>'.number_format($item['promotional_price'],0,',',' ').' F</strong>':($item['price']?number_format($item['price'],0,',',' ').' F':'Sur devis') ?></td><td><span class="status <?= $item['status']==='published'?'published':'draft' ?>"><?= htmlspecialchars($item['status']) ?></span></td><td><div class="table-actions"><a class="btn secondary" href="/admin/produits/modifier?id=<?= (int)$item['id'] ?>">Modifier</a><form method="post" action="/admin/produits/supprimer"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="btn secondary">Archiver</button></form></div></td><?php endif ?>
</tr><?php endforeach ?></tbody></table></div><?php if(!$items): ?><div class="admin-empty">Aucune donnée enregistrée pour le moment.</div><?php endif ?></section>
